MagickBooleanType SkipCompressedDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
  if ((image->blob->eof || !image->blob->extent))
    return MagickFalse;

  if (dds_info->mipmap_levels && (dds_info->is_texture || dds_info->is_cube_map)) {
    size_t width = dds_info->width;
    size_t height = dds_info->height;
    size_t offset = dds_info->data_offset;

    for (size_t level = 0; level < dds_info->mipmap_levels; level++) {
      size_t level_width = width > 1 ? width / 2 : 1;
      size_t level_height = height > 1 ? height / 2 : 1;

      size_t level_size = ((level_width + 3) / 4) * ((level_height + 3) / 4) * texel_size;

      offset += level_size;

      width = level_width;
      height = level_height;

      if (offset > image->blob->length)
        break;
    }

    if (offset > image->blob->length)
      return MagickFalse;

    if (SeekBlob(image, offset, 0) != (ssize_t)offset)
      return MagickFalse;
  }

  return MagickTrue;
}

MagickBooleanType SkipDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
  if (image == (Image *) NULL)
    return MagickFalse;

  if (dds_info->mipmap_levels > 1) {
    size_t offset = 0;
    size_t width = dds_info->width;
    size_t height = dds_info->height;

    for (size_t level = 1; level < dds_info->mipmap_levels; level++) {
      size_t block_width = (width + 3) >> 2;
      size_t block_height = (height + 3) >> 2;
      size_t block_count = block_width * block_height;
      size_t mipmap_size = block_count * texel_size;

      if (offset + mipmap_size > image->blob->length) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "CorruptImage", "Unable to skip mipmap images");
        return MagickFalse;
      }

      offset += mipmap_size;

      if (width > 1)
        width >>= 1;
      else
        width = 1;

      if (height > 1)
        height >>= 1;
      else
        height = 1;
    }

    image->blob->offset += offset;
  }

  return MagickTrue;
}

MagickBooleanType SkipDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
    ssize_t offset = 0;
    size_t level = 0;
    size_t width = dds_info->width;
    size_t height = dds_info->height;

    /* Check for unexpected end of file */
    if (image->blob != NULL && image->blob->length < (size_t)(offset + texel_size * (width / 4) * height))
        return MagickFalse;

    if ((dds_info->mipmaps != 0) && (dds_info->texture || dds_info->cubemap)) {
        while ((width > 0) || (height > 0)) {
            size_t level_width = width ? width / 2 : 1;
            size_t level_height = height ? height / 2 : 1;
            size_t level_size = ((level_width + 3) / 4) * ((level_height + 3) / 4) * texel_size;

            /* Seek over mipmap data */
            offset += level_size;

            /* Update width and height for next mipmap level */
            width = level_width;
            height = level_height;
            level++;

            /* Check for unexpected end of file */
            if (image->blob != NULL && image->blob->length < (size_t)offset)
                return MagickFalse;
        }
    }

    return MagickTrue;
}

MagickBooleanType SkipDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t offset = 0;
  size_t width = image->columns;
  size_t height = image->rows;
  size_t depth = 1;  // For cube maps, depth could be 6
  size_t level;

  if ((dds_info->mipmaps) && ((dds_info->texture_type == TextureType2D) || (dds_info->texture_type == TextureTypeCubeMap))) {
    for (level = 1; level < dds_info->mipmap_levels; level++) {
      size_t level_width = width >> level;
      size_t level_height = height >> level;
      size_t level_depth = depth;

      // Clamp to 1 for dimensions that have become 0
      if (level_width == 0) level_width = 1;
      if (level_height == 0) level_height = 1;

      // Calculate the size of the mipmap level in bytes
      size_t bytes_per_block = ((level_width + 3) / 4) * ((level_height + 3) / 4) * texel_size;
      size_t level_size = bytes_per_block * level_depth;

      // Seek to the next mipmap level
      offset += level_size;

      // Check for unexpected end of file
      if ((image->blob.pos + offset) > image->blob.length) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageWarning,
                                    "Unexpected end of file", "`%s'", image->filename);
        status = MagickFalse;
        break;
      }

      // Skip the mipmap data
      image->blob.pos += offset;
    }
  }

  return status;
}

MagickBooleanType SkipDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
  if (image->blob == (void *) NULL)
    return MagickFalse;

  if ((dds_info->mipmaps > 1UL) && ((dds_info->flags & 0x8) != 0) && ((dds_info->flags & 0x1000) != 0)) {
    for (unsigned int level = 1; level < dds_info->mipmaps; level++) {
      size_t width = (dds_info->width + 1) >> 1;
      size_t height = (dds_info->height + 1) >> 1;
      size_t size = ((width + 3) >> 2) * ((height + 3) >> 2) * (4UL * (dds_info->texel_size / 4));

      if (image->blob->length < size)
        return MagickFalse;

      image->blob->offset += size;
      image->blob->length -= size;
    }
  }

  return MagickTrue;
}
